H.background();
const w = H.W, h = H.H;
const ang = Math.min(85, Math.max(1, P.angle)) * Math.PI / 180;
const dist = Math.max(1, P.dist);
const height = dist * Math.tan(ang);
const gx = w * 0.20, gy = h * 0.84;
const sx = (w * 0.60) / 100;
const objX = Math.min(w - 60, gx + dist * sx);
const topY = Math.max(70, gy - Math.min(height, 100) * sx);
H.line(gx - 30, gy, w - 20, gy, { color: H.colors.axis, width: 2 });
H.line(objX, gy, objX, topY, { color: H.colors.accent2, width: 5 });
H.line(gx, gy, objX, topY, { color: H.colors.accent, width: 2, dash: [6, 5] });
H.line(gx, gy, objX, gy, { color: H.colors.good, width: 2, dash: [4, 4] });
const sweep = 0.5 + 0.5 * Math.sin(t * 1.2);
H.circle(gx + (objX - gx) * sweep, gy + (topY - gy) * sweep, 5 + Math.sin(t * 3), { fill: H.colors.warn });
H.circle(gx, gy, 6, { fill: H.colors.violet });
H.text("observer", gx - 24, gy + 20, { color: H.colors.sub, size: 12 });
H.text("height", objX + 8, (topY + gy) / 2, { color: H.colors.accent2, size: 12 });
H.text("theta = " + P.angle.toFixed(0) + "°", gx + 36, gy - 10, { color: H.colors.accent, size: 12 });
